<article class="project-card" @click="go('projects',p.id)" @keydown.enter="go('projects',p.id)" tabindex="0" role="link" :aria-label="p.name"><div class="project-card-top"><span class="project-icon" :style="`--project-color:${p.color}`" x-html="$icon('FolderClosed')"></span><span class="status-badge" :class="{'finished':progress(p)===100}" x-text="progress(p)===100?'تکمیل شده':'در حال انجام'"></span><span class="project-arrow" x-html="$icon('ArrowUpLeft')"></span></div><h3 x-text="p.name"></h3><p x-text="p.description"></p><div class="project-progress-label"><span>پیشرفت پروژه</span><strong x-text="fa(progress(p))+'٪'"></strong></div><div class="progress-track"><i :style="`width:${progress(p)}%;background:${p.color}`"></i></div><div class="project-metrics"><span><span x-html="$icon('LayoutGrid')"></span><span x-text="fa(p.stages.length)+' مرحله'"></span></span><span><span x-html="$icon('CheckCheck')"></span><span x-text="fa(tasks.filter(t=>t.project_id===p.id).length)+' تسک'"></span></span></div><div class="project-card-bottom"><div class="avatar-stack"><template x-for="m in p.members.slice(0,4)" :key="m.id"><span class="avatar tiny" :style="`background:${color(m.id)}`" :title="m.name" x-text="initials(m.name)"></span></template></div><span x-text="date(p.goal?.start_date)+' — '+date(p.goal?.end_date)"></span></div></article>
